WITH event_rows AS (SELECT b.mktcode,b.tgtcode,b.bizdate,b.lastPx / 10000.0>t.ma20 AND LAG(b.lastPx / 10000.0) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate)<=LAG(t.ma20) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate) AS matched FROM `newzl`.`hsj_stock_hq_basic` b LEFT JOIN `newzl`.`hsj_stock_hq_basic_technical` t ON t.mktcode=b.mktcode AND t.tgtcode=b.tgtcode AND t.bizdate=b.bizdate) SELECT mktcode,tgtcode,bizdate FROM event_rows WHERE bizdate='2026-04-14' AND matched=TRUE;
